// === Tab: mySketch ===
let isMobile = /iPhone|iPod|Android/i.test(navigator.userAgent);
let repel_radius, radius_, rSq;
let angle = 0;
let points = [];

// --- STATES ---
let showWASD = true; 
let mouseActive = true; 

// --- ATTRACTORS ---
let pAtt, aAtt; 
const pSpeed = 7;
const pReachSq = 202500; // 450^2

// --- PHYSICS ---
const particles = 20000; // Boosted for WebGL!
const attraction = 0.004;
const damping = 0.92;
let mouseStrength = 28; 

function setup() {
    // Enable WEBGL mode
    createCanvas(isMobile ? 360 : 900, isMobile ? 360 : 700, WEBGL);

    radius_ = isMobile ? 160 : 250;
    repel_radius = isMobile ? 60 : 90;
    rSq = repel_radius * repel_radius;

    pAtt = { x: -100, y: 0 };
    aAtt = { x: 100, y: 0 };

    pixelDensity(1);
    stroke(255);
    strokeWeight(2);

    for (let i = 0; i < particles; i++) {
        points.push({
            index: i,
            x: 0, y: 0,
            vx: 0, vy: 0
        });
    }
}

function keyPressed() {
    if (keyCode === 32) showWASD = !showWASD;      // SPACE
    if (keyCode === 13) mouseStrength *= -1;       // ENTER
    if (keyCode === 18) mouseActive = !mouseActive; // ALT
    return false; 
}

function draw() {
    background(0);
    // Note: No translate(width/2, height/2) needed in WEBGL; (0,0) is center

    // 1. Movement Logic
    if (keyIsDown(87)) pAtt.y -= pSpeed; // W
    if (keyIsDown(83)) pAtt.y += pSpeed; // S
    if (keyIsDown(65)) pAtt.x -= pSpeed; // A
    if (keyIsDown(68)) pAtt.x += pSpeed; // D

    if (keyIsDown(UP_ARROW))    aAtt.y -= pSpeed;
    if (keyIsDown(DOWN_ARROW))  aAtt.y += pSpeed;
    if (keyIsDown(LEFT_ARROW))  aAtt.x -= pSpeed;
    if (keyIsDown(RIGHT_ARROW)) aAtt.x += pSpeed;

    // 2. Draw Indicators
    noFill();
    stroke(showWASD ? "#00ffc8" : "#ff00c8");
    ellipse(pAtt.x, pAtt.y, 20, 20);

    stroke(255, 200, 0);
    rect(aAtt.x - 7.5, aAtt.y - 7.5, 15, 15);

    // Coordinate adjustment for mouse in WEBGL center-origin mode
    let mX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2;
    let mY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2;
    let isCtrlDown = keyIsDown(CONTROL);

    // 3. GPU-Friendly Loop
    beginShape(POINTS); // Use beginShape(POINTS) for mass point rendering
    for (let i = 0; i < particles; i++) {
        let p = points[i];
        let idx = p.index;

        // FORCE: Home Rotation
        let hX = Math.sin(idx + angle) * Math.sin(idx * idx) * radius_;
        let hY = Math.cos(idx * idx) * radius_;
        p.vx += (hX - p.x) * attraction;
        p.vy += (hY - p.y) * attraction;

        // FORCE: WASD Attractor
        if (showWASD) {
            let dx = pAtt.x - p.x;
            let dy = pAtt.y - p.y;
            let d2 = dx * dx + dy * dy;
            if (d2 < pReachSq) {
                let d = Math.sqrt(d2);
                let g = (1 - d / 450) * 0.8;
                p.vx += (dx / d) * g;
                p.vy += (dy / d) * g;
                p.vx += (dy / d) * 0.08; 
                p.vy -= (dx / d) * 0.08;
            }
        }

        // FORCE: Arrow Repeller (Ctrl)
        if (isCtrlDown) {
            var dx = p.x - aAtt.x; 
            var dy = p.y - aAtt.y;
            var d2 = dx * dx + dy * dy;
            if (d2 < pReachSq) {
                var d = Math.sqrt(d2);
                var g = (1 - d / 450) * 0.8;
                p.vx += (dx / d) * g;
                p.vy += (dy / d) * g;
            }
        }

        // FORCE: Mouse
        if (mouseActive) {
            var dx = p.x - mX;
            var dy = p.y - mY;
            var d2 = dx * dx + dy * dy;
            if (d2 < rSq && d2 > 0.1) {
                var d = Math.sqrt(d2);
                let pct = (1 - d / repel_radius) * mouseStrength;
                p.vx += (dx / d) * pct;
                p.vy += (dy / d) * pct;
            }
        }

        p.vx *= damping;
        p.vy *= damping;
        p.x += p.vx;
        p.y += p.vy;

        vertex(p.x, p.y); // Direct vertex call is faster in WEBGL
    }
    endShape();
    angle += 0.01;
}

